/**
 * struct Buffer - String manipulation buffer
 */
struct Buffer
{
  char *data;   ///< Pointer to data
  char *dptr;   ///< Current read/write position
  size_t dsize; ///< Length of data
};

struct FgetConv
{
  FILE *fp;
  iconv_t cd; ///< iconv conversion descriptor
  char bufi[512];
  char bufo[512];
  char *p;
  char *ob;
  char *ib;
  size_t ibl;
  const char **inrepls;
};

enum LookupType
{
  MUTT_LOOKUP_CHARSET, ///< Alias for another character set
  MUTT_LOOKUP_ICONV,   ///< Character set conversion
};

struct Tz
{
  char tzname[8];         ///< Name, e.g. UTC
  unsigned char zhours;   ///< Hours away from UTC
  unsigned char zminutes; ///< Minutes away from UTC
  bool zoccident;         ///< True if west of UTC, False if East
};

enum MuttStatType
{
  MUTT_STAT_ATIME, ///< File/dir's atime - last accessed time
  MUTT_STAT_MTIME, ///< File/dir's mtime - last modified time
  MUTT_STAT_CTIME, ///< File/dir's ctime - creation time
};

enum MuttOpenDirMode
{
  MUTT_OPENDIR_NONE,   ///< Plain opendir()
  MUTT_OPENDIR_CREATE, ///< Create the directory if it doesn't exist
};

struct MuttFileIter
{
  char *line;   ///< the line data
  size_t size;  ///< allocated size of line data
  int line_num; ///< line number
};

union HashKey
{
  const char *strkey;  ///< String key
  unsigned int intkey; ///< Integer key
};

struct HashElem
{
  int type;              ///< Type of data stored in Hash Table, e.g. #DT_STRING
  union HashKey key;     ///< Key representing the data
  void *data;            ///< User-supplied data
  struct HashElem *next; ///< Linked List
};
ARRAY_HEAD(HashElemArray, struct HashElem *);

struct HashWalkState
{
  size_t index;          ///< Current position in table
  struct HashElem *last; ///< Current element in linked list
};

struct ListNode
{
  char *data;                     ///< String
  STAILQ_ENTRY(ListNode) entries; ///< Linked list
};

struct LogLine
{
  time_t time;                   ///< Timestamp of the message
  const char *file;              ///< Source file
  int line;                      ///< Line number in source file
  const char *function;          ///< C function
  enum LogLevel level;           ///< Log level, e.g. #LL_DEBUG1
  char *message;                 ///< Message to be logged
  STAILQ_ENTRY(LogLine) entries; ///< Linked list
};

struct Mapping
{
  const char *name; ///< String value
  int value;        ///< Integer value
};

struct Md5Ctx
{
  md5_uint32 A;
  md5_uint32 B;
  md5_uint32 C;
  md5_uint32 D;

  md5_uint32 total[2];
  md5_uint32 buflen;
  md5_uint32 buffer[32];
};

struct NotifyCallback
{
  struct Notify  *current;       ///< Notify object being observed
  enum NotifyType event_type;    ///< Send: Event type, e.g. #NT_ACCOUNT
  int             event_subtype; ///< Send: Event subtype, e.g. #NT_ACCOUNT_ADD
  void           *event_data;    ///< Data from notify_send()
  void           *global_data;   ///< Data from notify_observer_add()
};

struct Observer
{
  enum NotifyType type;  ///< Notification type to observe, e.g. #NT_WINDOW
  observer_t callback;   ///< Callback function for events
  void *global_data;     ///< Private data to pass to callback
};

struct ObserverNode
{
  struct Observer *observer;          ///< An Observer
  STAILQ_ENTRY(ObserverNode) entries; ///< Linked list
};

enum PrexUrlQueryKeyValMatch
{
  PREX_URL_QUERY_KEY_VAL_MATCH_FULL,
  PREX_URL_QUERY_KEY_VAL_MATCH_KEY,
  PREX_URL_QUERY_KEY_VAL_MATCH_VAL,
  PREX_URL_QUERY_KEY_VAL_MATCH_MAX
};

enum PrexRfc2047EncodedWordMatch
{
  PREX_RFC2047_ENCODED_WORD_MATCH_FULL,
  PREX_RFC2047_ENCODED_WORD_MATCH_CHARSET,
  PREX_RFC2047_ENCODED_WORD_MATCH_ENCODING,
  PREX_RFC2047_ENCODED_WORD_MATCH_TEXT,
  PREX_RFC2047_ENCODED_WORD_MATCH_MAX
};

enum PrexGnuTlsCertHostnameMatch
{
  PREX_GNUTLS_CERT_HOST_HASH_MATCH_FULL,
  PREX_GNUTLS_CERT_HOST_HASH_MATCH_HOST,
  PREX_GNUTLS_CERT_HOST_HASH_MATCH_HASH,
  PREX_GNUTLS_CERT_HOST_HASH_MATCH_HASH_LAST,
  PREX_GNUTLS_CERT_HOST_HASH_MATCH_MAX
};

enum PrexAccountCmd
{
  PREX_ACCOUNT_CMD_MATCH_FULL,
  PREX_ACCOUNT_CMD_MATCH_KEY,
  PREX_ACCOUNT_CMD_MATCH_VALUE,
  PREX_ACCOUNT_CMD_MATCH_MAX
};

enum PrexAliasTags
{
  PREX_ALIAS_TAGS_MATCH_FULL,
  PREX_ALIAS_TAGS_MATCH_PRE,
  PREX_ALIAS_TAGS_MATCH_KEY,
  PREX_ALIAS_TAGS_MATCH_TAGS,
  PREX_ALIAS_TAGS_MATCH_POST,
  PREX_ALIAS_TAGS_MATCH_MAX,
};

struct qm_trace {
	unsigned long	 lastline;
	unsigned long	 prevline;
	const char	*lastfile;
	const char	*prevfile;
};

struct Regex
{
  char *pattern;  ///< printable version
  regex_t *regex; ///< compiled expression
  bool pat_not;   ///< do not match
};

struct RegexNode
{
  struct Regex *regex;             ///< Regex containing a regular expression
  STAILQ_ENTRY(RegexNode) entries; ///< Linked list
};

struct Replace
{
  struct Regex *regex;           ///< Regex containing a regular expression
  size_t nmatch;                 ///< Match the 'nth' occurrence (0 means the whole expression)
  char *templ;                   ///< Template to match
  STAILQ_ENTRY(Replace) entries; ///< Linked list
};

struct Slist
{
  struct ListHead head; ///< List containing values
  size_t count;         ///< Number of values in list
  uint32_t flags;       ///< Flags controlling list, e.g. #D_SLIST_SEP_SPACE
};

struct State
{
  FILE       *fp_in;   ///< File to read from
  FILE       *fp_out;  ///< File to write to
  const char *prefix;  ///< String to add to the beginning of each output line
  StateFlags  flags;   ///< Flags, e.g. #STATE_DISPLAY
  int         wraplen; ///< Width to wrap lines to (when flags & #STATE_DISPLAY)
};

